<?php require_once __DIR__.'/../includes/auth.php';$id=filter_input(INPUT_GET,'id',FILTER_VALIDATE_INT);$st=$pdo->prepare('SELECT * FROM suppliers WHERE id=?');$st->execute([$id]);$r=$st->fetch();if(!$r){flash('error','Supplier not found.');redirect('index.php');}$st=$pdo->prepare('SELECT id,name,sku,quantity FROM products WHERE supplier_id=? ORDER BY name');$st->execute([$id]);$products=$st->fetchAll();$pageTitle='Supplier details';$base='/shop-inventory-management';require __DIR__.'/../includes/header.php';require __DIR__.'/../includes/sidebar.php';?>
<div class="page-heading"><div><h1><?=e($r['name'])?></h1><p>Supplier details and linked products.</p></div><div><a class="btn" href="index.php">← Back</a> <a class="btn primary" href="edit.php?id=<?=$id?>">Edit supplier</a></div></div><div class="detail-grid"><div class="panel detail-card"><h2>Contact information</h2><p><span>Phone</span><strong><?=e($r['phone']?:'—')?></strong></p><p><span>Email</span><strong><?=e($r['email']?:'—')?></strong></p><p><span>Address</span><strong><?=nl2br(e($r['address']?:'—'))?></strong></p><p><span>Created</span><strong><?=e($r['created_at'])?></strong></p></div><div class="panel"><div class="panel-header"><div><h2>Linked products</h2><p><?=count($products)?> product(s)</p></div></div><div class="table-wrap"><table><thead><tr><th>Product</th><th>SKU</th><th>Stock</th></tr></thead><tbody><?php if(!$products):?><tr><td colspan="3" class="empty">No products linked.</td></tr><?php else:foreach($products as $p):?><tr><td><?=e($p['name'])?></td><td><?=e($p['sku'])?></td><td><?=$p['quantity']?></td></tr><?php endforeach;endif;?></tbody></table></div></div></div><?php require __DIR__.'/../includes/footer.php';?>
